import{_ as t,o as a,c as o,a5 as n}from"./chunks/framework.Cooo9kuv.js";const i=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"772批量移动指定文件夹下指定层级的文件夹到目标文件夹内","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["文件及文件夹批处理"],"标签":["指定层级","指定层级文件夹","移动指定层级文件夹"]},"headers":[],"relativePath":"md/文件及文件夹批处理/772批量移动指定文件夹下指定层级的文件夹到目标文件夹内.md","filePath":"md/文件及文件夹批处理/772批量移动指定文件夹下指定层级的文件夹到目标文件夹内.md"}'),s={name:"md/文件及文件夹批处理/772批量移动指定文件夹下指定层级的文件夹到目标文件夹内.md"};function e(p,r,g,l,_,b){return a(),o("div",null,[...r[0]||(r[0]=[n('<h3 id="批量移动指定层级文件夹到目标文件夹内" tabindex="-1">批量移动指定层级文件夹到目标文件夹内 <a class="header-anchor" href="#批量移动指定层级文件夹到目标文件夹内" aria-label="Permalink to &quot;批量移动指定层级文件夹到目标文件夹内&quot;">​</a></h3><p>比如有指定文件夹A，下有多个子文件夹，A文件夹层级默认为0级文件夹，可以将A文件夹下指定第几级文件夹移动动目标文件夹里</p><p><strong>是选择复制还是移动可以自行选择</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250614172417174989305715453.png" alt=""></p><h3 id="使用场景例子展示" tabindex="-1">使用场景例子展示 <a class="header-anchor" href="#使用场景例子展示" aria-label="Permalink to &quot;使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多文件（A文件夹为0级文件夹），同时有B、C、D....等文件夹（这些文件夹为一级文件夹），B、C、D....等这些文件夹下边还有子文件夹（这些子文件夹为2级文件夹），子文件夹下也有文件。</p><p>【操作方法】：只需要输入A文件夹路径，输入需要移动到的文件夹路径，输入2表示移动二级文件夹，然后选择复制还是移动即可，支持子文件夹自动穿透。</p><p>【1】、支持的文件格式：文件夹移动或复制</p><p>【2】、是否支持子文件夹穿透：支持</p><h3 id="📑-文件结构树示意" tabindex="-1">📑 文件结构树示意 <a class="header-anchor" href="#📑-文件结构树示意" aria-label="Permalink to &quot;📑 文件结构树示意&quot;">​</a></h3><p>若指定移动第 2 级文件夹，程序将移动 <strong>子文件夹B1</strong> **子文件夹B2 子文件夹C1 子文件夹D1 **到目标文件夹。</p><p><strong>文件夹A/ (主文件夹)</strong><br> ├── 文件1<br> ├── 文件2<br> ├── <strong>B/ (子文件夹)</strong><br> │   ├── 文件3<br> │   ├── <strong>子文件夹B1/</strong><br> │   │   ├── 文件4<br> │   │   └── <strong>子文件夹B1a/</strong><br> │   │       └── 文件5<br> │   └── <strong>子文件夹B2/</strong><br> │       └── 文件6<br> │       ... (B文件夹下可能还有更多子文件夹和文件)<br> ├── <strong>C/ (子文件夹)</strong><br> │   ├── 文件7<br> │   └── <strong>子文件夹C1/</strong><br> │       ├── 文件8<br> │       └── <strong>子文件夹C1a/</strong><br> │           └── 文件9<br> │           ... (C1a文件夹下可能还有更多嵌套)<br> └── <strong>D/ (子文件夹)</strong><br>     ├── 文件10<br>     └── <strong>子文件夹D1/</strong><br>         └── 文件11<br>         ... (D1文件夹下可能还有更多文件)<br><strong>... (A文件夹下可能还有更多子文件夹如E/F/G等)</strong></p><p>注意：先测试备份原文件再批量使用</p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20250720161512175299931253029.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统</p><p>注意事项：win32位系统以及mac系统需要额外定制开发</p><p><strong>2、使用期限</strong>： 无需注册、无需密码、不绑定电脑、无使用时间限制</p><p><strong>3、如何安装</strong>：不需要安装，按照说明使用即可</p><p><strong>特别注意 - 特别声明</strong>：请先测试，注意备份原文件，避免不可逆损失，之后再批量使用</p></blockquote><h3 id="📑-友情提示" tabindex="-1">📑 友情提示 <a class="header-anchor" href="#📑-友情提示" aria-label="Permalink to &quot;📑 友情提示&quot;">​</a></h3><p><strong>正式使用前请先测试/备份原文件，然后再大批量使用，以免造成不可逆损失。</strong></p><h2 id="📑源代码下载" tabindex="-1">📑源代码下载 <a class="header-anchor" href="#📑源代码下载" aria-label="Permalink to &quot;📑源代码下载&quot;">​</a></h2><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/1869.html" target="_blank" rel="noreferrer">https://www.softbangong.com/1869.html</a></p>',22)])])}const c=t(s,[["render",e]]);export{i as __pageData,c as default};
